                assert(pre.clients.dom().contains(i));
                assert(post.slots.dom().contains(i));
                assert(pre.slots.dom().contains(i));
                assert(post.clients.index(i) == pre.clients.index(i));
                assert(post.slots.index(i) == pre.slots.index(i));
